class ShoppingCart {
  items: string[] = [];
  add(item: string) { this.items.push(item); }
}

class CheckoutService {
  finalize(cart: ShoppingCart) {
    while (cart.items.length) {
      cart.items.pop();
    }
  }
}

class Customer { address: { street: string; city: string } }
class Order { customer: Customer; items: string[] }

class OrderProcessor {
  printShippingLabel(order: Order) {
    const addr = order.customer.address;
    return `${addr.street}, ${addr.city}`;
  }
}

// Version A
class AccountA { balance: number }
class PaymentProcessorA {
  charge(a: AccountA, amount: number) {
    a.balance -= amount;
  }
}

// Version B
class AccountB {
  private balance: number;
  debit(amount: number) { this.balance -= amount; }
}
class PaymentProcessorB {
  charge(a: AccountB, amount: number) { a.debit(amount); }
}
